        case Calendar.THURSDAY:
            weekday = "Thursday";
            break;
        case Calendar.FRIDAY:
            weekday = "Friday";
            break;
        case Calendar.SATURDAY:
            weekday = "Saturday";
            break;
        default:
            throw new IllegalArgumentException("Invalid date: " + date);
    }
    return weekday;
}

