public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int start = n/20;
    int end = n - (n/20);
    double sum = 0;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }
    return sum / (end - start);
}

public double trimMean(int[] arr) {
    // Step 1: Sort the array
    Arrays.sort(arr);

    // Step 2: Remove the smallest 5% and largest 5% of the elements
    int numToRemove = arr.length / 20;
    int[] trimmedArr = Arrays.copyOfRange(arr, numToRemove, arr.length - numToRemove);

    // Step 3: Calculate the mean
    double sum = 0;
    for (int i = 0; i < trimmedArr.length; i++) {
        sum += trimmedArr[i];
    }
    return sum / trimmedArr.length;
}

