    int arrLen = arr.length;
    int removeNum = (int) (arrLen / 20);
    int startIdx = removeNum;
    int endIdx = arrLen - removeNum - 1;
    double sum = 0;
    for (int i = startIdx; i <= endIdx; i++) {
        sum += sortedArr[i];
    }
    return sum / (arrLen - 2 * removeNum);
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    int[] sum = new int[k];
    for (int i = 0; i < n; i++) {
        int rem = arr[i] % k;
        if (rem == 0) {
            sum[0]++;
        } else {
            sum[rem]++;
        }
    }
    for (int i = 1; i < k; i++) {
        if (n / 2 != sum[i]) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1 || k < 2) {
        return false;
    }
    boolean[] visited = new boolean[k];
    for (int i = 0; i < n; i += 2) {
        int a = arr[i] % k;
        int b = arr[i + 1] % k;
        if (a == 0 && b == 0) {
            return false;
        }
        if (a == 0) {
            if (visited[b]) {
                return false;
            }
            visited[b] = true;
        } else if (b == 0) {
            if (visited[a]) {
                return false;
            }
            visited[a] = true;
        } else if (a == b) {
            return false;
        } else {
            if (visited[a] && visited[b]) {
                return false;
            }
            visited[a] = true;
            visited[b] = true;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    boolean[] used = new boolean[n];
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            int sum = 0;
            used[i] = true;
            for (int j = i + 1; j < n; j++) {
                if (!used[j]) {
                    sum += arr[j];
                    used[j] = true;
                }
            }
            if (sum % k != 0) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Iterate through the array and check if the sum of each pair is divisible by k
    for (int i = 0; i < arr.length - 1; i += 2) {
        if (arr[i] + arr[i + 1] % k != 0) {
            return false;
        }
    }

    // If the array is length is odd, check if the last element is divisible by k
    if (arr.length % 2 == 1 && arr[arr.length - 1] % k != 0) {
        return false;
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    int[] sums = new int[k];
    Arrays.fill(sums, 0);
    for (int i = 0; i < n / 2; i++) {
        int a = arr[i], b = arr[n - 1 - i];
        sums[a % k] += b;
        sums[b % k] += a;
    }
    for (int i = 0; i < k; i++) {
        if (sums[i] % k != 0) return false;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    for (int i = 0; i < n; i++) {
        dist[i] = Integer.MAX_VALUE;
    }
    dist[0] = 0;
    for (int i = 0; i < n - 1; i++) {
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int w = edge[2];
            if (dist[u] != Integer.MAX_VALUE && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
            }
        }
    }
    int minTime = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && dist[i] != Integer.MAX_VALUE) {
            minTime = Math.min(minTime, dist[i]);
        }
    }
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Initialize a visited array to track nodes that have been visited
    boolean[] visited = new boolean[n];

    // Initialize the minimum time to collect all apples as 0
    int minTime = 0;

    // Mark node 0 as visited
    visited[0] = true;

    // Add node 0 to the queue
    queue.add(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int node = queue.remove();

        // If the current node has an apple, increment the minimum time
        if (hasApple[node]) {
            minTime++;
        }

        // Loop through the adjacent nodes of the current node
        for (int neighbor : graph.adjacencyList.get(node)) {
            // If the adjacent node has not been visited, mark it as visited and add it to the queue
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    // Return the minimum time required to collect all apples and return to node 0
    return minTime;
}

