    Arrays.fill(times, 1);
    for (int i = 0; i < edges.length; i++) {
        int u = edges[i][0];
        int v = edges[i][1];
        times[v] = Math.max(times[u] + 1, times[v]);
    }
    int maxTime = 0;
    for (int i = 0; i < n; i++) {
