public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] e : edges) {
        graph.get(e[0]).add(e[1]);
        graph.get(e[1]).add(e[0]);
    }

    int[] visited = new int[n];
    Deque<Integer> queue = new ArrayDeque<>();
    queue.offer(0);
    visited[0] = 1;

    int time = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        time++;
        for (int i = 0; i < size; i++) {
            int node = queue.poll();
            for (int neighbor : graph.get(node)) {
                if (hasApple[neighbor]) {
                    return time;
                }
                if (visited[neighbor] == 0) {
                    visited[neighbor] = 1;
                    queue.offer(neighbor);
                }
            }
        }
    }
    return time;
}

public String sortString(String s) {
    String result = "";
    char[] chars = s.toCharArray();

    // step 1: pick the smallest character from s and append it to the result
    char smallest = Integer.MAX_VALUE;
    for (char c : chars) {
        if (c < smallest) {
            smallest = c;
        }
    }
    result += smallest;

    // step 2: pick the smallest character from s which is greater than the last appended character to the result and append it
    while (true) {
        char currentSmallest = Integer.MAX_VALUE;
        for (char c : chars) {
            if (c > smallest && c < currentSmallest) {
                currentSmallest = c;
            }
        }
        if (currentSmallest == Integer.MAX_VALUE) {
            break;
        }
        smallest = currentSmallest;
        result += smallest;
    }

    // step 3: repeat step 2 until you cannot pick more characters

    // step 4: pick the largest character from s and append it to the result
    char largest = Integer.MIN_VALUE;
    for (char c : chars) {
        if (c > largest) {
            largest = c;
        }
    }
    result += largest;

    // step 5: pick the largest character from s which is smaller than the last appended character to the result and append it
    while (true) {
        char currentLargest = Integer.MIN_VALUE;
        for (char c : chars) {
            if (c < largest && c > currentLargest) {
                currentLargest = c;
            }
        }
        if (currentLargest == Integer.MIN_VALUE) {
            break;
        }
        largest = currentLargest;
        result += largest;
    }

    // step 6: repeat step 5 until you cannot pick more characters

    // step 7: repeat the steps from 1 to 6 until you pick all characters from s

    return result;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    String result = new String(chars);
    for (int i = 0; i < s.length(); i++) {
        if (i + 1 < s.length()) {
            int nextSmaller = findSmaller(s, i + 1);
            if (nextSmaller != -1) {
                result += s.charAt(nextSmaller);
            }
        }
        if (i + 1 < s.length()) {
            int nextLarger = findLarger(s, i + 1);
            if (nextLarger != -1) {
                result += s.charAt(nextLarger);
            }
        }
    }
    return result;
}

private int findSmaller(String s, int start) {
    char current = s.charAt(start);
    int min = start;
    for (int i = start + 1; i < s.length(); i++) {
        if (s.charAt(i) < current && s.charAt(i) != 0) {
            min = i;
        }
    }
    return min;
}

private int findLarger(String s, int start) {
    char current = s.charAt(start);
    int max = start;
    for (int i = start + 1; i < s.length(); i++) {
        if (s.charAt(i) > current && s.charAt(i) != 0) {
            max = i;
        }
    }
    return max;
}

