    String result = "";
    for (int i = 0; i < chars.length; i++) {
        int smallest = i;
        for (int j = i; j < chars.length; j++) {
            if (chars[j] < chars[smallest]) {
                smallest = j;
            }
        }
        result += chars[smallest];
    }
    for (int i = chars.length - 1; i >= 0; i--) {
        int largest = i;
        for (int j = i; j >= 0; j--) {
            if (chars[j] > chars[largest]) {
                largest = j;
            }
        }
        result += chars[largest];
    }
    return result;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;
    int sum = 0;
    for (int num : nums) sum += num;
    int avg = sum / n;
    if (avg * n != sum) return false;
    int[] left = new int[n / 2];
    int[] right = new int[n - n / 2];
    for (int i = 0; i < n; i++) {
        if (i < n / 2) left[i] = nums[i];
        else right[i - n / 2] = nums[i];
    }
    return left.length == n / 2 && right.length == n - n / 2 && leftAverage(left) == rightAverage(right);
}

private int leftAverage(int[] left) {
    int sum = 0;
    for (int num : left) sum += num;
    return sum / left.length;
}

private int rightAverage(int[] right) {
    int sum = 0;
    for (int num : right) sum += num;
    return sum / right.length;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;
    int sum = 0;
    for (int num : nums) sum += num;
    int avg = sum / n;
    int leftSum = 0;
    int rightSum = sum;
    for (int i = 0; i < n - 1; i++) {
        leftSum += nums[i];
        rightSum -= nums[i];
        if (leftSum == rightSum) return true;
    }
    return false;
}

