public boolean splitArraySameAverage(int[] nums) {
    double sum = Arrays.stream(nums).sum();
    double avg = sum / nums.length;
    double leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
    }
    double leftAvg = leftSum / (nums.length / 2);
    double rightSum = 0;
    for (int i = nums.length / 2; i < nums.length; i++) {
        rightSum += nums[i];
    }
    double rightAvg = rightSum / (nums.length - nums.length / 2);
    return avg == leftAvg && avg == rightAvg;
}

public boolean splitArraySameAverage(int[] nums) {
    double avg = getAverage(nums);
    int leftSum = 0;
    int rightSum = 0;
    for (int i = 0; i < nums.length; i++) {
        if (i % 2 == 0) {
            leftSum += nums[i];
        } else {
            rightSum += nums[i];
        }
    }
    return leftSum == rightSum && leftSum == avg * nums.length / 2;
}

private double getAverage(int[] nums) {
    double sum = 0;
    for (int num : nums) {
        sum += num;
    }
    return sum / nums.length;
}

