public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return cost[0];
    } else if (n == 2) {
        return Math.min(cost[0], cost[1]);
    } else {
        int first = cost[0], second = cost[1];
        for (int i = 2; i < n; i++) {
            int temp = first;
            first = Math.min(first, second + cost[i]);
            second = temp;
        }
        return first;
    }
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return cost[0];
    } else if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int dp0 = cost[0], dp1 = cost[1], dp2 = cost[0] + cost[1];
    for (int i = 2; i < n; i++) {
        int dp = Math.min(dp0 + cost[i], Math.min(dp1 + cost[i], dp2 + cost[i]));
        dp0 = dp1;
        dp1 = dp2;
        dp2 = dp;
    }
    return Math.min(dp0, Math.min(dp1, dp2));
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }
    if (cost.length == 2) {
        return Math.min(cost[0], cost[1]);
    }
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

