}

public int minInsertions(String s) {
    Stack<Character> stack = new Stack<>();
    int count = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            stack.push(c);
        } else {
            if (stack.isEmpty()) {
                count++;
            } else {
                stack.pop();
            }
        }
    }

    while (!stack.isEmpty()) {
        stack.pop();
        count++;
    }

    return count;
}

