public int findMinFibonacciNumbers(int k) {
    int[] fibonacciNumbers = new int[k+1];
    fibonacciNumbers[1] = 1;
    fibonacciNumbers[2] = 1;
    for (int i = 3; i <= k; i++) {
        fibonacciNumbers[i] = fibonacciNumbers[i-1] + fibonacciNumbers[i-2];
    }
    int minNumberOfFibonacciNumbers = 0;
    for (int i = 1; i <= k; i++) {
        if (k - fibonacciNumbers[i] >= 0) {
            k -= fibonacciNumbers[i];
            minNumberOfFibonacciNumbers++;
        }
        else {
            break;
        }
    }
    return minNumberOfFibonacciNumbers;
}

public int findMinFibonacciNumbers(int k) {
    int minFibonacciNumbers = 0;
    int fib1 = 1, fib2 = 1;
    while (k > 0) {
        if (fib1 + fib2 <= k) {
            minFibonacciNumbers++;
            k -= fib1;
            fib1 = fib2;
            fib2 = fib1 + fib2;
        } else {
            k -= fib2;
            fib2 = fib1 + fib2;
        }
    }
    return minFibonacciNumbers;
}

public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[k + 1];
    fib[1] = 1;
    fib[2] = 1;
    for (int i = 3; i <= k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    int min = Integer.MAX_VALUE;
    for (int i = 1; i <= k; i++) {
        if (fib[i] == k) {
            return i;
        } else if (fib[i] < k && fib[i] < min) {
            min = fib[i];
        }
    }
    return min;
}

public int findMinFibonacciNumbers(int k) {
    int[] fibonacciSequence = new int[] {1, 1};
    int count = 2;
    while (fibonacciSequence[count - 1] < k) {
        int nextNumber = fibonacciSequence[count - 1] + fibonacciSequence[count - 2];
        fibonacciSequence[count] = nextNumber;
        count++;
    }
    int min = count - 1;
    for (int i = count - 1; i >= 0; i--) {
        if (k - fibonacciSequence[i] >= 0) {
            min = Math.min(min, i + 1);
            k -= fibonacciSequence[i];
        }
    }
    return min;
}

