    if (n == 1) {
        return String.valueOf((char)('a' + k - 1));
    }
    String smallest = getSmallestString(n - 1, k / ('z' - 'a' + 1));
    return smallest + (char)('a' + k % ('z' - 'a' + 1) - 1);
}

