    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (mat[i][j] == 1) {
                dp[i][j] = 1;
                for (int k = 0; k < j; k++) {
                    if (mat[i][k] == 1) {
                        dp[i][j] = Math.max(dp[i][j], dp[i][k] + 1);
                    }
                }
                for (int k = 0; k < i; k++) {
                    if (mat[k][j] == 1) {
                        dp[i][j] = Math.max(dp[i][j], dp[k][j] + 1);
                    }
                }
                maxLen = Math.max(maxLen, dp[i][j]);
            }
        }
    }

    return maxLen;
}

public static int longestLine(int[][] mat) {
