    for (int i = 0; i < mat.length; i++) {
        // Iterate through each column
        for (int j = 0; j < mat[0].length; j++) {
            // If the current element is 1, then check for the longest line in the current direction
            if (mat[i][j] == 1) {
                // Check horizontal line
                int length = getLongestLineLength(mat, i, j, 0, 1);
                maxLength = Math.max(maxLength, length);

                // Check vertical line
                length = getLongestLineLength(mat, i, j, 1, 0);
                maxLength = Math.max(maxLength, length);

                // Check diagonal line
                length = getLongestLineLength(mat, i, j, 1, 1);
                maxLength = Math.max(maxLength, length);

                // Check anti-diagonal line
                length = getLongestLineLength(mat, i, j, 1, -1);
                maxLength = Math.max(maxLength, length);
            }
        }
    }

    return maxLength;
}

