    int n = mat[0].length;

    int[][] maxLineLengths = new int[m][n];
    for (int i = 0; i < m; i++) {
        Arrays.fill(maxLineLengths[i], 0);
    }

    // Initialize the first row
    for (int i = 0; i < n; i++) {
        if (mat[0][i] == 1) {
            maxLineLengths[0][i] = 1;
        }
    }

    // Initialize the first column
    for (int i = 1; i < m; i++) {
        if (mat[i][0] == 1) {
            maxLineLengths[i][0] = 1;
        }
    }

    // Fill in the rest of the matrix
    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            if (mat[i][j] == 1) {
                maxLineLengths[i][j] = 1;
                maxLineLengths[i][j] = Math.max(maxLineLengths[i][j], maxLineLengths[i][j-1] + 1);
                maxLineLengths[i][j] = Math.max(maxLineLengths[i][j], maxLineLengths[i-1][j] + 1);
                maxLineLengths[i][j] = Math.max(maxLineLengths[i][j], maxLineLengths[i-1][j-1] + 1);
                maxLineLengths[i][j] = Math.max(maxLineLengths[i][j], maxLineLengths[i-1][j+1] + 1);
            }
        }
    }

    // Find the maximum length
    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (maxLineLengths[i][j] > maxLength) {
                maxLength = maxLineLengths[i][j];
            }
        }
    }

    return maxLength;
}

