public static int squarePermutations(int[] A) {
    int N = A.length;
    // Compute the sum of each pair of adjacent elements
    int[] sums = new int[N - 1];
    for (int i = 0; i < N - 1; i++) {
        sums[i] = A[i] + A[i + 1];
    }

    // Compute the square root of each sum
    int[] squareRoots = new int[N - 1];
    for (int i = 0; i < N - 1; i++) {
        squareRoots[i] = (int) Math.sqrt(sums[i]);
    }

    // Check if each square root is equal to the sum of its two adjacent elements
    int count = 0;
    for (int i = 0; i < N - 1; i++) {
        if (squareRoots[i] == sums[i]) {
            count++;
        }
    }

    // Return the number of square permutations
    return count;
}

