    for (int i = 0; i < n + m - 1; i++) {
        int startRow = Math.max(i - m + 1, 0);
        int endRow = Math.min(i, n - 1);
        int startCol = Math.max(m - i - 1, 0);
        int endCol = Math.min(i, m - 1);
        for (int row = startRow; row <= endRow; row++) {
            result[k++] = mat[row][startCol + row];
        }
        for (int col = startCol + 1; col <= endCol; col++) {
