public static int findSmallestInteger(int n) {
    // Find the number of digits in the input number
    int numDigits = (int) (Math.log10(n) + 1);

    // Check if the input number is smaller than the number of digits
    if (n < numDigits) {
        return -1;
    }

    // Rearrange the digits of the input number in increasing order
    int[] digits = new int[numDigits];
    for (int i = 0; i < numDigits; i++) {
        digits[i] = n % 10;
        n /= 10;
    }
    Arrays.sort(digits);

    // Construct the smallest rearranged integer
    int smallest = 0;
    for (int i = 0; i < numDigits; i++) {
        smallest = smallest * 10 + digits[i];
    }

    return smallest;
}

