public static int findSmallestInteger(int n) {
    String num = String.valueOf(n);
    int smallest = -1;
    for (int i = 0; i < num.length(); i++) {
        int digit = num.charAt(i) - '0';
        int swapIndex = -1;
        for (int j = i + 1; j < num.length(); j++) {
            if (num.charAt(j) - '0' < digit) {
                swapIndex = j;
                break;
            }
        }
        if (swapIndex != -1) {
            char temp = num.charAt(i);
            num = num.substring(0, i) + num.charAt(swapIndex) + num.substring(i + 1, swapIndex) + temp + num.substring(swapIndex + 1);
            smallest = Integer.parseInt(num);
            break;
        }
    }
    return smallest;
}

