    int x1 = points[0][0], x2 = points[1][0], x3 = points[2][0];
    int y1 = points[0][1], y2 = points[1][1], y3 = points[2][1];
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) == 0) && (x1 * (x2 - x3) + x2 * (x3 - x1) + x3 * (x1 - x2) == 0);
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) return false;
    Point a = new Point(points[0][0], points[0][1]);
    Point b = new Point(points[1][0], points[1][1]);
    Point c = new Point(points[2][0], points[2][1]);
    if (a.equals(b) || b.equals(c) || c.equals(a)) return false;
    return (a.crossProduct(b) * c.crossProduct(b) < 0) && (a.crossProduct(c) * b.crossProduct(c) < 0);
}

public static boolean isBoomerang(int[][] points) {
    // Check if the array of points is null or has less than 3 elements
    if (points == null || points.length < 3) {
        return false;
    }

    // Calculate the dot product of the vectors
    double dotProduct = 0;
    for (int i = 0; i < points.length; i++) {
        int[] point1 = points[i];
        int[] point2 = points[(i + 1) % points.length];
        dotProduct += (point1[0] - point2[0]) * (point1[1] - point2[1]);
    }

    // Check if the dot product is positive, negative or zero
    if (dotProduct > 0) {
        return true;
    } else if (dotProduct < 0) {
        return false;
    } else {
        // If the dot product is zero, check if the points are collinear
        return areCollinear(points);
    }
}

private static boolean areCollinear(int[][] points) {
    // Check if the array of points is null or has less than 3 elements
    if (points == null || points.length < 3) {
        return false;
    }

    // Calculate the cross product of the vectors
    double crossProduct = 0;
    for (int i = 0; i < points.length; i++) {
        int[] point1 = points[i];
        int[] point2 = points[(i + 1) % points.length];
        crossProduct += (point1[0] - point2[0]) * (point1[1] + point2[1]);
    }

    // Check if the cross product is zero
    return Math.abs(crossProduct) < 1e-9;
}

public static boolean isBoomerang(int[][] points) {
    return points.length == 3 && isCollinear(points[0], points[1], points[2]) && !points[0][0].equals(points[1][0]) && !points[1][0].equals(points[2][0]);
}

private static boolean isCollinear(int[] p1, int[] p2, int[] p3) {
    return p1[0] * (p2[1] - p3[1]) + p2[0] * (p3[1] - p1[1]) + p3[0] * (p1[1] - p2[1]) == 0;
}

