public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int result = 0;
    for (int i = 1; i * i <= n; i++) {
        if ((n - i * i) % 2 == 0) {
            result++;
        }
    }
    return result;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int sqrt = (int) Math.sqrt(n);
        count++;
        n -= sqrt * sqrt;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    // Initialize the minimum number of perfect square numbers to 0
    int minSquares = 0;
    // Initialize the target number
    int target = n;
    // While the target number is greater than 0
    while (target > 0) {
        // Find the largest perfect square number that is less than or equal to the target number
        int square = (int) Math.sqrt(target);
        // If the target number is not a perfect square, decrease the target number by the square and increment the minimum number of perfect square numbers
        if (square * square != target) {
            target -= square;
            minSquares++;
        // Otherwise, the target number is a perfect square, so the minimum number of perfect square numbers is the number of perfect squares found so far
        } else {
            return minSquares + 1;
        }
    }
    // Return the minimum number of perfect square numbers
    return minSquares;
}

